{
  "name": "@aislop-inc/opencode-mem",
  "version": "2.41.2",
  "description": "OpenCode plugin that gives coding agents persistent memory using local Turso/libSQL vector search",
  "type": "module",
  "main": "dist/plugin.js",
  "types": "dist/plugin.d.ts",
  "exports": {
    ".": {
      "import": "./dist/plugin.js",
      "types": "./dist/plugin.d.ts"
    },
    "./server": {
      "import": "./dist/plugin.js",
      "types": "./dist/plugin.d.ts"
    },
    "./v2": {
      "import": "./dist/v2/plugin.js",
      "types": "./dist/v2/plugin.d.ts"
    },
    "./tui": {
      "import": "./dist/tui.js",
      "types": "./dist/tui.d.ts"
    },
    "./tags": {
      "import": "./dist/services/tags.js",
      "types": "./dist/services/tags.d.ts"
    }
  },
  "scripts": {
    "build": "rm -rf dist && bunx tsc && bun run web:build",
    "web:dev": "cd web && bun run dev",
    "web:build": "cd web && bun run build",
    "dev": "tsc --watch",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "lint": "eslint . --max-warnings=0",
    "format": "prettier --write .",
    "format:check": "prettier --check .",
    "check": "bun run format:check && bun run lint && bun run typecheck",
    "prepare": "husky"
  },
  "keywords": [
    "opencode",
    "plugin",
    "memory",
    "vector-database",
    "ai",
    "coding-agent",
    "local",
    "standalone"
  ],
  "author": "opencode-mem",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AISlop-Inc/opencode-mem.git"
  },
  "homepage": "https://github.com/AISlop-Inc/opencode-mem#readme",
  "bugs": {
    "url": "https://github.com/AISlop-Inc/opencode-mem/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@huggingface/transformers": "^4.3.1",
    "@libsql/client": "^0.18.0",
    "@opencode-ai/plugin": "^1.19.0",
    "@opencode-ai/sdk": "^1.19.0",
    "@opencode/plugin": "^2.0.27",
    "@tursodatabase/database": "^0.8.3",
    "franc-min": "^6.2.0",
    "iso-639-3": "^3.0.1",
    "onnxruntime-node": "1.31.1",
    "zod": "^4.6.7"
  },
  "//": "Pin latest stable onnxruntime-node@1.31.1 (direct + override) with @huggingface/transformers: nested OpenCode installs ignore package overrides (#184); Ort::Env teardown fix shipped in 1.24.1 (#225). Intel Mac (darwin/x64) is unsupported — @tursodatabase/database and fixed onnxruntime releases ship no x64 binding.",
  "overrides": {
    "onnxruntime-node": "1.31.1",
    "bun-types": "1.3.14"
  },
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "@types/bun": "^1.4.3",
    "eslint": "^10.12.0",
    "eslint-config-prettier": "^10.1.8",
    "globals": "^17.13.0",
    "husky": "^9.1.7",
    "lint-staged": "^17.6.0",
    "prettier": "^3.9.10",
    "prettier-plugin-astro": "^1.1.2",
    "prettier-plugin-svelte": "^4.1.1",
    "typescript": "6.0.3",
    "typescript-eslint": "^8.71.2"
  },
  "opencode": {
    "type": "plugin",
    "hooks": [
      "chat.message",
      "chat.params",
      "event"
    ]
  },
  "files": [
    "dist",
    "package.json"
  ],
  "lint-staged": {
    "*.{js,mjs,cjs,ts}": [
      "eslint --fix",
      "prettier --write"
    ],
    "*.svelte": [
      "prettier --write"
    ],
    "*.astro": [
      "prettier --write"
    ],
    "*.{css,html,json,jsonc,md,yml,yaml}": [
      "prettier --write"
    ]
  }
}
